BEGIN TRANSACTION READ ONLY; SET LOCAL statement_timeout = '10s'; SET LOCAL lock_timeout = '2s'; WITH selected AS ( SELECT DISTINCT tr.tgfoid AS oid FROM pg_catalog.pg_trigger tr JOIN pg_catalog.pg_class c ON c.oid = tr.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'storage' AND c.relname IN ('buckets', 'objects') AND NOT tr.tgisinternal UNION SELECT p.oid FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'storage' AND p.proname = 'foldername' AND pg_catalog.oidvectortypes(p.proargtypes) = 'text' ) SELECT n.nspname AS schema_name, p.proname, pg_catalog.pg_get_function_identity_arguments(p.oid) AS identity_arguments, pg_catalog.pg_get_function_result(p.oid) AS result_type, l.lanname AS language, p.prosecdef AS security_definer, pg_catalog.pg_get_userbyid(p.proowner) AS owner, pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)) AS definition_md5 FROM selected s JOIN pg_catalog.pg_proc p ON p.oid = s.oid JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace JOIN pg_catalog.pg_language l ON l.oid = p.prolang ORDER BY 1, 2, 3; ROLLBACK;
